/// <param name="Sdk">The SDK that signed in, from <c>X-Orvano-SDK</c>; null when none was sent.</param>
/// <param name="IpAddress">The IP address last seen for the session; null when unknown.</param>
/// <param name="Current">Whether this is the session making the call.</param>
/// <param name="Method">How the session began.</param>
/// <param name="Provider">The provider of an <c>oauth</c> or <c>id_token</c> session; null for every other method.</param>
/// <param name="Aal">How strongly the session signed in: 1 for one factor, 2 once a second factor or a passkey was verified on it. Also the access token's <c>aal</c> claim.</param>
/// <param name="Amr">The ways the user proved who they are on this session, sorted: <c>pwd</c>, <c>email</c>, <c>fed</c>, <c>otp</c>, <c>rec</c>, <c>hwk</c>, <c>swk</c>, <c>user</c>, and <c>mfa</c> (whenever <c>aal</c> is 2). Also the access token's <c>amr</c> claim.</param>
public sealed record Session(
    [property: JsonPropertyName("id")] string Id,
    [property: JsonPropertyName("createdAt")] DateTimeOffset CreatedAt,
    [property: JsonPropertyName("lastRefreshedAt")] DateTimeOffset LastRefreshedAt,
    [property: JsonPropertyName("userAgent")] string? UserAgent,
    [property: JsonPropertyName("sdk")] string? Sdk,
    [property: JsonPropertyName("ipAddress")] string? IpAddress,
    [property: JsonPropertyName("current")] bool Current,
    [property: JsonPropertyName("method")] SessionMethod Method,
    [property: JsonPropertyName("provider")] OAuthProvider? Provider,
    [property: JsonPropertyName("aal")] int Aal,
    [property: JsonPropertyName("amr")] IReadOnlyList<string> Amr);

/// <summary>One page of a user's active sessions, newest first.</summary>
/// <param name="Items">The sessions on this page.</param>
/// <param name="NextCursor">Pass it as <c>cursor</c> to get the next page; null on the last page.</param>
public sealed record SessionPage(
    [property: JsonPropertyName("items")] IReadOnlyList<Session> Items,
    [property: JsonPropertyName("nextCursor")] string? NextCursor);

/// <summary>A table, read live from Postgres.</summary>
/// <param name="Name">The table name.</param>
/// <param name="Database">The slug of the database it is in.</param>
/// <param name="Columns">Every column, in order.</param>
/// <param name="Readable">False when the table has no primary key, so its rows can't be listed through the API.</param>
/// <param name="Writable">True only for a table whose primary key is the standard <c>id uuid</c>; others are read only through the API.</param>
/// <param name="EstimatedRows">Postgres' estimate of the row count; null when the table was never analyzed.</param>
public sealed record Table(
    [property: JsonPropertyName("name")] string Name,
    [property: JsonPropertyName("database")] string Database,
    [property: JsonPropertyName("columns")] IReadOnlyList<Column> Columns,
    [property: JsonPropertyName("readable")] bool Readable,
    [property: JsonPropertyName("writable")] bool Writable,
    [property: JsonPropertyName("estimatedRows")] long? EstimatedRows);

/// <summary>One page of a database's tables, by name.</summary>
/// <param name="Items">The tables on this page.</param>
/// <param name="NextCursor">Pass it as <c>cursor</c> to get the next page; null on the last page.</param>
public sealed record TablePage(
    [property: JsonPropertyName("items")] IReadOnlyList<Table> Items,
    [property: JsonPropertyName("nextCursor")] string? NextCursor);

/// <summary>Sets whether a user's email is verified.</summary>
/// <param name="Verified">True marks it verified (keeping an earlier date); false marks it unverified.</param>
public sealed record UpdateEmailVerificationRequest(
    [property: JsonPropertyName("verified")] bool Verified);

/// <summary>Changes a user's email at once, without a confirmation email.</summary>
/// <param name="Email">The new email, trimmed, at most 320 characters. Unique in the project, ignoring case.</param>
/// <param name="EmailVerified">True marks the new email verified; it is unverified otherwise. Defaults to false.</param>
public sealed record UpdateUserEmailRequest(
    [property: JsonPropertyName("email")] string Email,
    [property: JsonPropertyName("emailVerified"), JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)] bool? EmailVerified = null);

/// <summary>A user of a project.</summary>
/// <param name="Id">The user ID.</param>
/// <param name="Email">The email, as typed at sign up; null for a user without one.</param>
/// <param name="EmailVerified">Whether the email has been verified. Also the access token's <c>email_verified</c> claim.</param>
/// <param name="EmailVerifiedAt">When the email was verified; null while it is not.</param>
/// <param name="Name">The display name; null when none was given.</param>
/// <param name="Status">Whether the user may sign in.</param>
/// <param name="Metadata">Your own data about the user: a JSON object of at most 16 KB.</param>
/// <param name="CreatedAt">When the user signed up.</param>
/// <param name="LastSignInAt">When the user last signed in; null if never.</param>
/// <param name="Providers">The providers linked to the user, sorted by name.</param>
/// <param name="HasPassword">Whether the user has a password.</param>
/// <param name="MfaEnabled">Whether MFA is on: the user has confirmed an authenticator app and the project allows it. A passkey alone never turns it on.</param>
/// <param name="IsAnonymous">Whether the user is a guest from <c>account.createAnonymousSession</c>: no email, name, or password until they upgrade with <c>account.upgradeAnonymous</c> or link a provider. Also the access token's <c>is_anonymous</c> claim.</param>
public sealed record User(
    [property: JsonPropertyName("id")] string Id,
    [property: JsonPropertyName("email")] string? Email,
    [property: JsonPropertyName("emailVerified")] bool EmailVerified,
    [property: JsonPropertyName("emailVerifiedAt")] DateTimeOffset? EmailVerifiedAt,
    [property: JsonPropertyName("name")] string? Name,
    [property: JsonPropertyName("status")] UserStatus Status,
    [property: JsonPropertyName("metadata")] IReadOnlyDictionary<string, JsonElement> Metadata,
    [property: JsonPropertyName("createdAt")] DateTimeOffset CreatedAt,
    [property: JsonPropertyName("lastSignInAt")] DateTimeOffset? LastSignInAt,
    [property: JsonPropertyName("providers")] IReadOnlyList<OAuthProvider> Providers,
    [property: JsonPropertyName("hasPassword")] bool HasPassword,
    [property: JsonPropertyName("mfaEnabled")] bool MfaEnabled,
    [property: JsonPropertyName("isAnonymous")] bool IsAnonymous);

/// <summary>One page of a project's users, newest first.</summary>
/// <param name="Items">The users on this page.</param>
/// <param name="NextCursor">Pass it as <c>cursor</c> to get the next page; null on the last page.</param>
public sealed record UserPage(
    [property: JsonPropertyName("items")] IReadOnlyList<User> Items,
    [property: JsonPropertyName("nextCursor")] string? NextCursor);
